// Temp live runtime check (NOT committed): workerd + real publisher network.
import { Miniflare, convertV4MiniflareOptions, Log, LogLevel } from 'miniflare';
import net from 'node:net';

const port = await new Promise((resolve) => { const s = net.createServer(); s.listen(0, '127.0.0.1', () => { const p = s.address().port; s.close(() => resolve(p)); }); });
const mf = new Miniflare(convertV4MiniflareOptions({
  cf: false, port, host: '127.0.0.1', log: new Log(LogLevel.ERROR),
  name: 'positivity-bias', scriptPath: 'dist/worker.js', modules: true, compatibilityDate: '2026-10-13',
  durableObjects: { NEWS: { className: 'NewsStore', useSQLite: true } },
  assets: { directory: 'public', binding: 'ASSETS', run_worker_first: ['/api/*'], routerConfig: { has_user_worker: true } },
  bindings: { REWRITES_PER_REFRESH: '0' }
}));
try {
  await mf.ready;
  const ns = await mf.getDurableObjectNamespace('NEWS');
  const refresh = await ns.get(ns.idFromName('edition')).fetch('https://news.internal/refresh', { method: 'POST' });
  console.log('refresh', refresh.status, JSON.stringify(await refresh.json()));
  const data = await (await mf.dispatchFetch(`http://127.0.0.1:${port}/api/news?limit=120`)).json();
  console.log('status sources:', data.sources.map((s) => `${s.id}=${s.state}(${s.received})`).join(' '));
  for (const id of ['ynet', 'kan', 'n12', 'mako']) {
    const list = data.articles.filter((a) => a.sourceId === id);
    const cats = [...new Set(list.map((a) => a.categories.join('|') || '(none)'))];
    console.log(`${id}: n=${list.length} categories=${JSON.stringify(cats)}`);
    if (list[0]) console.log(`   sample: ${list[0].originalHeadline.slice(0, 60)} | ${list[0].url}`);
  }
} finally { await mf.dispose(); }

