  assert.equal(plainText('<script>steal()</script><p>שלום &amp; עולם</p>'), 'שלום & עולם');
  assert.deepEqual(validateWebsites(configuration).map((website) => website.domain), ['ynet.co.il', 'kan.org.il', 'n12.co.il', 'mako.co.il']);
