```js
export function budgetDecision(used, estimate, budget) {
  if (!Number.isFinite(budget) || budget <= 0) return { allowed: false, reason: 'budget_disabled' };
  if (used + estimate > budget) return { allowed: false, reason: 'budget_exhausted', remaining: Math.max(0, budget - used) };
  return { allowed: true, remaining: budget - (used + estimate) };
}
